const helpers={connect,subscribe,publish,parse,decodePublish,evaluate};if(typeof module!=='undefined')module.exports=helpers;if(!root.document)return;let host,state,socket=null,heartbeat=null,connectTimeout=null,rx=new Uint8Array(),ready=false,epoch=0,pending=Promise.resolve(),status='未连接',lastSource='本地手动数据';const E=x=>root.escapeHTML(x);const save=()=>{const snapshot=JSON.parse(JSON.stringify(state));pending=pending.catch(()=>{}).then(()=>root.api('application_lab','POST',snapshot));return pending};
function log(direction,t,payload){state.events.unshift({at:new Date().toISOString(),direction,topic:t,payload:String(payload).slice(0,2000)});state.events=state.events.slice(0,80);showEvents();save().catch(e=>root.toast('日志未保存：'+e.message))}
