function refreshStatus(){const el=host?.querySelector('#mqttStatus');if(el)el.textContent=status}
function showEvents(){const el=host?.querySelector('#messageLog');if(el)el.innerHTML=state.events.map(e=>`<tr><td>${new Date(e.at).toLocaleTimeString('zh-CN')}</td><td>${E(e.direction)}</td><td>${E(e.topic)}</td><td><code>${E(e.payload)}</code></td></tr>`).join('')||'<tr><td colspan="4" class="empty">尚无事件</td></tr>'}
function feedback(v){const el=host?.querySelector('#appFeedback');if(el)el.innerHTML=`<div class="metric-strip"><div><span>温度</span><strong>${v.temperature}<small>°C</small></strong></div><div><span>湿度</span><strong>${v.humidity}<small>%</small></strong></div><div><span>风机逻辑</span><strong style="font-size:21px">${v.fan?'开启':'关闭'}</strong></div></div><div style="height:150px;display:flex;align-items:center;justify-content:center;gap:35px;background:#f2f6fa;border:1px solid #dce5ee"><div style="perspective:500px"><div style="width:100px;height:65px;transform:rotateY(-25deg) rotateX(10deg);border:2px solid #9eb4c9;background:${v.alarm?'#fae5df':'#e0edf2'};display:grid;place-items:center">教学温室</div></div><span style="font-size:42px;color:${v.fan?'#267da6':'#9baab8'}">✥</span><span class="badge ${v.alarm?'red':''}">${v.alarm?'规则触发':'阈值正常'}</span></div><p class="muted">来源：${E(lastSource)}；规则：temperature &gt; ${v.threshold} → fan=true。输出仅驱动本页虚拟元件，未自动发送控制指令。</p>`}
