async function open(){disconnect();const url=host.querySelector('#mqttUrl').value.trim(),t=host.querySelector('#mqttTopic').value.trim();let parsed;try{parsed=new URL(url)}catch{throw Error('请输入有效 wss:// 教学 Broker 地址')}if(parsed.protocol!=='wss:'||parsed.username||parsed.password||parsed.search||parsed.hash)throw Error('仅支持无嵌入凭据或查询参数的 wss:// 地址');topic(t,true);if(!confirm('连接到 '+parsed.host+' 并订阅 '+t+'？这会把客户端标识和主题发送给你指定的教学 Broker。仅使用已获授权的教学环境。'))return;const token=++epoch;status='建立连接中';refreshStatus();socket=new WebSocket(url,['mqtt']);socket.binaryType='arraybuffer';rx=new Uint8Array();const ws=socket;connectTimeout=setTimeout(()=>{if(epoch===token&&!ready){status='连接超时';try{ws.close()}catch{}refreshStatus()}},12000);ws.onopen=()=>{if(epoch!==token)return;ws.send(connect('loglab_'+Math.random().toString(36).slice(2,14)))};ws.onmessage=async e=>{if(epoch!==token)return;try{if(!(e.data instanceof ArrayBuffer))throw Error('服务器未返回 MQTT 二进制数据');rx=join(rx,new Uint8Array(e.data));const out=parse(rx);rx=out.rest;for(const frame of out.frames){const kind=frame.type>>4;if(kind===2){if(frame.body.length!==2||frame.body[1]!==0)throw Error('Broker 拒绝连接，代码 '+frame.body[1]);clearTimeout(connectTimeout);ready=true;status='已连接，等待订阅确认';refreshStatus();ws.send(subscribe(t));heartbeat=setInterval(()=>{if(ws.readyState===1)ws.send(new Uint8Array([192,0]))},20000)}else if(kind===9){if(frame.body.length<3||frame.body.slice(2).some(v=>v===128))throw Error('订阅被拒绝');status='订阅已确认';refreshStatus();log('连接',t,'MQTT 3.1.1 SUBACK 已确认')}else if(kind===3){const m=decodePublish(frame);if(m.qos===1)ws.send(new Uint8Array([64,2,m.id>>8,m.id&255]));log('收到消息',m.topic,m.payload);try{await usePayload(m.payload,'真实 MQTT 接收：'+m.topic)}catch(error){log('数据校验失败',m.topic,error.message)}}}}catch(error){log('协议错误','',error.message);disconnect()}};ws.onerror=()=>{if(epoch===token){status='连接错误，请检查地址、TLS 与 Broker 的 WebSocket 设置';refreshStatus()}};ws.onclose=()=>{if(epoch===token){ready=false;clearInterval(heartbeat);clearTimeout(connectTimeout);status='连接已关闭';refreshStatus()}}}
function renderView(){host.innerHTML=`<div class="page-head"><div><div class="eyebrow">APPLICATION DEVELOPMENT / 消息与虚拟反馈</div><h1>应用开发实验台</h1><p class="muted">验证 JSON 数据契约、配置控制规则，观察虚拟元件反馈；可手动接入授权教学 Broker</p></div><span class="badge gray" id="mqttStatus">${status}</span></div><div class="workspace-split"><section class="card"><h2>数据 → 规则 → 应用结果</h2><p class="muted">本地运行不访问外网。右侧连接需由你主动确认；未建立连接时不会显示虚构实时数据。</p><label class="field">输入 JSON<textarea id="appJson" rows="6">${E(JSON.stringify({temperature:28,humidity:62},null,2))}</textarea></label><label class="field">触发温度阈值 °C<input id="appThreshold" type="number" min="-50" max="100" value="${state.threshold}"></label><div class="toolbar"><button class="btn primary" id="runLocal">运行本地规则</button><button class="btn" id="publishMessage">发布到指定教学 Broker</button><button class="btn" id="exportApp">导出实验记录</button></div><div id="appFeedback"></div><h3>Python 接入示例（在本页不执行）</h3><p class="muted">设备端可以用任意 MQTT 客户端发布含 temperature 和 humidity 的 JSON。本工作台实际执行 JSON 校验和规则，未在浏览器中解释 Python。</p><pre style="white-space:pre-wrap;background:#f4f6f9;padding:14px;font-size:12px">import json
payload = json.dumps({"temperature": 28, "humidity": 62})
# client 为你已配置并连接的设备端 MQTT 客户端
client.publish("classroom/telemetry", payload, qos=0)</pre></section><section class="card"><h2>真实 MQTT 可选连接</h2><span class="badge gray">未配置默认服务器</span><p class="muted">只支持 MQTT 3.1.1 over WSS 匿名教学 Broker、QoS 0 发布/订阅；无自动重连。端点不得含密钥。连接状态来自真实协议应答。</p><label class="field">WebSocket 端点<input id="mqttUrl" placeholder="wss://你的授权教学服务器/mqtt" autocomplete="off"></label><label class="field">订阅主题 / 发布主题<input id="mqttTopic" value="classroom/telemetry" maxlength="200"></label><div class="toolbar"><button class="btn primary" id="connectMQTT">连接并订阅</button><button class="btn" id="disconnectMQTT">断开</button></div><p class="muted">切换页面会断开连接。不保存端点或认证信息，不自动把虚拟执行器状态发布到设备。需要账号密码、TCP MQTT 或设备协议网关的环境暂不支持。</p><a href="https://docs.oasis-open.org/mqtt/mqtt/v3.1.1/mqtt-v3.1.1.html" target="_blank" rel="noreferrer">MQTT 3.1.1 协议说明</a></section></div><section class="card" style="margin-top:20px"><h2>消息与运行记录</h2><div class="table-scroll"><table><thead><tr><th>时间</th><th>事件</th><th>来源 / 主题</th><th>数据</th></tr></thead><tbody id="messageLog"></tbody></table></div></section>`;const bind=(id,fn)=>host.querySelector('#'+id).onclick=()=>Promise.resolve().then(fn).catch(e=>root.toast(e.message));bind('runLocal',()=>usePayload(host.querySelector('#appJson').value,'本地手动 JSON'));bind('connectMQTT',open);bind('disconnectMQTT',disconnect);bind('exportApp',()=>root.downloadJSON('application-lab.json',state));bind('publishMessage',()=>{if(!ready||socket?.readyState!==1)throw Error('尚未建立真实 MQTT 连接');const t=host.querySelector('#mqttTopic').value.trim(),text=host.querySelector('#appJson').value;evaluate(text,host.querySelector('#appThreshold').value);topic(t);if(!confirm('向已连接教学 Broker 的 '+t+' 发布当前 JSON？请确认该主题不会触发未经授权的真实设备。'))return;socket.send(publish(t,text));log('已发送（QoS0无交付确认）',t,text)});showEvents();if(state.last){lastSource='已保存的上次实验记录';feedback(state.last)}}
